SELECT DECODE(COUNT(*), 0, 'POPUP_NO', 'POPUP_YES') AS DOOSAN_FLAG 
  FROM POIFLOAD_DOOS 
 WHERE COM_CODE =#{st_buyer}    
   AND LEGACY_PO_NO = #{LEGACY_PO_NO}
   AND DESTINATION_TYPE = 'INVENTORY'

mapper.update:

UPDATE WMSSTCK SET AVAIL_QTY = NVL(AVAIL_QTY,0)+ (#{INV_QTY}),
                   ALLOC_QTY = NVL(ALLOC_QTY,0)-(#{INV_QTY}),
                   STC_SELLER_PRICE = ROUND(DECODE(NVL(AVAIL_QTY,0)+(#{INV_QTY}),0,0,((NVL(AVAIL_QTY,0)*NVL(STC_SELLER_PRICE,0))+(#{INV_QTY}*#{UNIT_PRICE})) / (NVL(AVAIL_QTY,0)+#{INV_QTY})),0), 
	CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	CHANGE_USER = #{USER_ID}
WHERE WAREHOUSE_CODE = #{st_ware_house_code}  
  AND STDCATLG_ID = #{STDCATLG_ID}	 
  AND AGENT = (SELECT AGENT FROM WMSIVDT WHERE BUYER = #{st_buyer}    AND INV_NO = #{st_IK_NO}  AND INV_SEQ = #{IK_SEQ} )


